void Studio::runAdditiveTransportTick(){
    auto put=[&](const char* name,bool ok){transportResults.getDynamicObject()->setProperty(name,ok);};
    if(transportTicks==3700){perform(stop);cancelNoteTool(false);PopupMenu::dismissAllActiveMenus();project=emptyProject();project.bpm=120;project.loop=false;project.title="Additive native verification";project.patterns[0].length=4;currentFile={};selectedTrack=7;lane()={{0,2,60,.8f}};selectedNotes.clear();selectedNote=-1;undoStack.clear();redoStack.clear();publish();setSize(1180,800);resetLayout();put("nativeAdditiveRecall",applySynthPreset(factorySynthPresets()[59],7)&&project.tracks[7].instrument==Instrument::additive);perform(synthTab,0);snapshot(transportReport.getSiblingFile("native-additive.png"));editSynthValue(25);auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());put("nativeAdditiveDialog",dialog&&dialog->getTextEditor("value"));if(dialog){dialog->getTextEditor("value")->setText("0.42");dialog->exitModalState(1);}}
    if(transportTicks==3710){put("nativeAdditiveTyped",project.tracks[7].synth.harmonics[0]==.42f);perform(undoAction);put("nativeAdditiveUndo",project.tracks[7].synth.harmonics[0]==1);perform(redoAction);put("nativeAdditiveRedo",project.tracks[7].synth.harmonics[0]==.42f);perform(synthTab,2);snapshot(transportReport.getSiblingFile("native-additive-tone.png"));put("nativeAdditiveTone",synthPage==2);perform(synthTab,1);snapshot(transportReport.getSiblingFile("native-additive-envelope.png"));put("nativeAdditiveEnvelope",synthPage==1);perform(synthTab,0);engine->observedPeak.store(0);perform(play);transportFrames=engine->processedFrames.load();}
    if(transportTicks==3730){put("nativeAdditiveAudio",engine->playing.load()&&engine->processedFrames.load()>transportFrames&&engine->observedPeak.load()>.001f);perform(stop);auto file=transportReport.getSiblingFile("native-additive.pulse");Project read;put("nativeAdditiveProject",saveProject(project,file).wasOk()&&loadProject(file,read).wasOk()&&read.tracks[7].synth==project.tracks[7].synth&&read.tracks[7].instrument==Instrument::additive);auto sound=factorySynthPresets()[59];sound.patch=project.tracks[7].synth;auto exchange=transportReport.getSiblingFile("native-additive.pulsesound");SynthPreset loaded;put("nativeAdditiveExchange",saveSynthPreset(sound,exchange).wasOk()&&loadSynthPreset(exchange,loaded).wasOk()&&loaded.patch==sound.patch);put("nativeAdditiveLibrary",putPersonalSound(soundLibraryFile(),{"user-native-additive",sound},false,soundLibraryToken(soundLibraryFile())).wasOk()&&recallLibrarySound("user-native-additive"));auto rev=revision;editSynthValue(26);auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());if(dialog){changed(false);dialog->getTextEditor("value")->setText("0.9");dialog->exitModalState(1);}put("nativeAdditiveStaleQueued",revision!=rev);}
    if(transportTicks==3740){put("nativeAdditiveStale",project.tracks[7].synth.harmonics[1]==0);recording=true;auto before=project.tracks[7].synth;put("nativeAdditiveRecording",!changeSynthValue(25,.9)&&project.tracks[7].synth==before);recording=false;editSynthValue(40);if(auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent()))dialog->exitModalState(0);}
    if(transportTicks==3750){put("nativeAdditiveCancel",!Component::getCurrentlyModalComponent()&&project.tracks[7].synth.harmonics[15]==.12f);perform(stop);}
}
